{
  "task_summary": "Predict whether an ACS respondent changed residence within the last year.",
  "ranking": [
    {
      "rank": 1,
      "feature": "AGEP",
      "rationale": "Life stage is a stable, strong driver of residential mobility."
    },
    {
      "rank": 2,
      "feature": "MAR",
      "rationale": "Marital status reflects household formation and stability relevant to moving."
    },
    {
      "rank": 3,
      "feature": "RELP",
      "rationale": "Household role captures durable family and living-arrangement constraints."
    },
    {
      "rank": 4,
      "feature": "PINCP",
      "rationale": "Personal income affects ability and incentive to move across states."
    },
    {
      "rank": 5,
      "feature": "ESR",
      "rationale": "Employment status is semantically tied to job-related and economic moves."
    },
    {
      "rank": 6,
      "feature": "SCHL",
      "rationale": "Educational attainment proxies life stage and opportunity without being purely geographic."
    },
    {
      "rank": 7,
      "feature": "COW",
      "rationale": "Class of worker indicates job stability and mobility constraints."
    },
    {
      "rank": 8,
      "feature": "WKHP",
      "rationale": "Usual work hours measure labor-force attachment relevant to residential stability."
    },
    {
      "rank": 9,
      "feature": "JWMNP",
      "rationale": "Commute time can indicate housing-job mismatch, though it is infrastructure-dependent."
    },
    {
      "rank": 10,
      "feature": "MIL",
      "rationale": "Military status can directly affect relocation but is tied to state-specific bases."
    },
    {
      "rank": 11,
      "feature": "DIS",
      "rationale": "Disability may constrain moving but has weaker and heterogeneous effects."
    },
    {
      "rank": 12,
      "feature": "GCL",
      "rationale": "Grandparent caregiving reflects household obligations that may reduce mobility."
    },
    {
      "rank": 13,
      "feature": "CIT",
      "rationale": "Citizenship relates to migration history but risks demographic shortcut learning."
    },
    {
      "rank": 14,
      "feature": "NATIVITY",
      "rationale": "Nativity may reflect migration background but is demographically confounded."
    },
    {
      "rank": 15,
      "feature": "SEX",
      "rationale": "Sex has limited direct semantic connection to moving and may encode shortcuts."
    },
    {
      "rank": 16,
      "feature": "DREM",
      "rationale": "Cognitive difficulty can affect independence but is sparse and partly redundant with disability."
    },
    {
      "rank": 17,
      "feature": "DEAR",
      "rationale": "Hearing difficulty has weak direct relevance to residential mobility."
    },
    {
      "rank": 18,
      "feature": "DEYE",
      "rationale": "Vision difficulty has weak direct relevance and is mostly a health proxy."
    },
    {
      "rank": 19,
      "feature": "ESP",
      "rationale": "Parental employment status is age-conditional and likely brittle outside specific subgroups."
    },
    {
      "rank": 20,
      "feature": "RAC1P",
      "rationale": "Race can encode structural and geographic disparities, making it risky for OOD generalization."
    },
    {
      "rank": 21,
      "feature": "ANC",
      "rationale": "Ancestry is highly demographic and geographic, making it especially prone to state-specific artifacts."
    }
  ]
}
